ControlledOutcomeTag.inputs:
@if(
  equals(outputs('DecisionValuesValid'), false),
  'adaQuest-ReviewRequired',
  if(
    equals(outputs('SafeAutoClose'), true),
    'adaQuest-AutoClosed',
    if(
      or(
        equals(triggerBody()?['RecommendedAction'], 'Escalate'),
        equals(triggerBody()?['Verdict'], 'True Positive')
      ),
      'adaQuest-Escalation',
      if(
        or(
          equals(triggerBody()?['RecommendedAction'], 'Remediate'),
          equals(
            triggerBody()?['RequiresContainmentOrRemediation'],
            'Yes'
          )
        ),
        'adaQuest-RemediationRequired',
        'adaQuest-ReviewRequired'
      )
    )
  )
)

FinalIncidentLabels.inputs:
@union(
  coalesce(
    outputs('IncidentRecord')?['labels'],
    json('[]')
  ),
  createArray(
    json(
      '{"labelName":"adaQuest-Triaged","labelType":"User"}'
    ),
    json(
      concat(
        '{"labelName":"',
        outputs('ControlledOutcomeTag'),
        '","labelType":"User"}'
      )
    )
  )
)

EscalationStateVerified.inputs:
@and(
  equals(
    toLower(string(outputs('EscalatedIncidentRecord')?['status'])),
    'active'
  ),
  contains(
    toLower(string(outputs('EscalatedIncidentRecord')?['labels'])),
    'adaquest-triaged'
  ),
  contains(
    toLower(string(outputs('EscalatedIncidentRecord')?['labels'])),
    'adaquest-escalation'
  ),
  or(
    and(
      outputs('OwnerMustBePreserved'),
      equals(
        toLower(concat(
          trim(string(outputs('EscalatedIncidentRecord')?['owner']?['objectId'])), '|',
          trim(string(outputs('EscalatedIncidentRecord')?['owner']?['userPrincipalName'])), '|',
          trim(string(outputs('EscalatedIncidentRecord')?['owner']?['email'])), '|',
          trim(string(outputs('EscalatedIncidentRecord')?['owner']?['assignedTo']))
        )),
        outputs('OwnerFingerprintToPreserve')
      )
    ),
    and(
      not(outputs('OwnerMustBePreserved')),
      or(
        empty(outputs('NormalizedEscalationAssigneeUPN')),
        equals(
          toLower(string(outputs('EscalatedIncidentRecord')?['owner']?['userPrincipalName'])),
          outputs('NormalizedEscalationAssigneeUPN')
        ),
        equals(
          toLower(string(outputs('EscalatedIncidentRecord')?['owner']?['email'])),
          outputs('NormalizedEscalationAssigneeUPN')
        )
      )
    )
  )
)
